package com.interview.fraud.casework;
import com.interview.fraud.transaction.TransactionEntity; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="investigation_cases")
public class CaseEntity { @Id public UUID id; @Column(name="case_number") public String caseNumber; @OneToOne @JoinColumn(name="transaction_id") public TransactionEntity transaction; public String status; @Column(name="deterministic_score") public int deterministicScore; @Column(name="risk_level") public String riskLevel; @Column(name="assigned_to") public String assignedTo; @Column(name="recommended_action") public String recommendedAction; @Column(name="approved_action") public String approvedAction; @Version public long version; @Column(name="created_at") public Instant createdAt; @Column(name="updated_at") public Instant updatedAt; protected CaseEntity(){} public CaseEntity(TransactionEntity t,int score){id=UUID.randomUUID();caseNumber="CASE-"+t.externalId;transaction=t;deterministicScore=score;riskLevel=score>=70?"HIGH":score>=40?"MEDIUM":"LOW";status="OPEN";createdAt=updatedAt=Instant.now();}}
